  /**
   * @method
   * @name hashkey#fetchTime
   * @description fetches the current integer timestamp in milliseconds from the
   * exchange server
   * @see https://hashkeyglobal-apidoc.readme.io/reference/check-server-time
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {int} the current integer timestamp in milliseconds from the
   * exchange server
   */
  std::shared_future<ccxt::any>
  fetchTime(ccxt::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> ccxt::any {
                        ccxt::any response =
                            awaitValue(this->publicGetApiV1Time(params));
                        //
                        //     {
                        //         "serverTime": 1721661553214
                        //     }
                        //
                        return this->safeInteger(response,
                                                 std::string("serverTime"));
                      })
        .share();
  }

  /**
   * @method
   * @name hashkey#fetchStatus
   * @description the latest known information on the availability of the
   * exchange API
   * @see https://hashkeyglobal-apidoc.readme.io/reference/test-connectivity
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a [status structure]{@link
   * https://docs.ccxt.com/?id=exchange-status-structure}
   */
  std::shared_future<ccxt::any>
  fetchStatus(ccxt::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> ccxt::any {
                        ccxt::any response =
                            awaitValue(this->publicGetApiV1Ping(params));
                        //
                        // {}
                        //
                        return ccxt::dict{
                            {std::string("status"), std::string("ok")},
                            {std::string("updated"), ccxt::any{}},
                            {std::string("eta"), ccxt::any{}},
                            {std::string("url"), ccxt::any{}},
                            {std::string("info"), response},
                        };
                      })
        .share();
  }

